    due: hoHm_(t.due), stores: txt_(t.stores, 300) || 'All', photo: !!t.photo, active: t.active !== false, order: i + 1 })).filter(t => t.task);
  if (!list.length) throw new Error('The list is empty.');
  const sh = xtab_(HO_TPL_TAB, HO_TPL_H), now = new Date(), n = sh.getLastRow() - 1;
  if (n > 0) sh.getRange(2, 1, n, HO_TPL_H.length).clearContent();
  sh.getRange('E:E').setNumberFormat('@');
  sh.getRange(2, 1, list.length, HO_TPL_H.length).setValues(list.map(t => [t.id, t.shift, t.order, t.task, t.due, t.stores, t.photo ? 'Y' : '', t.active ? 'Yes' : 'No', user.name, now]));
  sh.getRange('E:E').setNumberFormat('@');
  try { append_('log', [[new Date(), 'Task list setup saved (' + list.length + ' tasks)', user.name]]); } catch (e) { }
  return { list: hoTpl_(), locs: hoLocs_(), saved: true };
}
